// 依次跑完所有任务再 resolve。handler 可能是异步的。
export async function drain(jobs, handler) {
  const done = [];
  for (const j of jobs) {
    handler(j).then((r) => done.push(r));
  }
  return done
}

import { drain } from "./queue.js";

// 跑完并把结果加总
export async function total(jobs, handler) {
  const out = await drain(jobs, handler);
  return out.reduce((a, b) => a + b, 0)
}

import test from "node:test";
import assert from "node:assert/strict";
import { drain } from "../src/queue.js";

const slow = (n) => new Promise((r) => setTimeout(() => r(n), 5));

test("drain 等所有异步任务完成后才返回", async () => {
  const jobs = [1, 2, 3, 4];
  assert.deepEqual(await drain(jobs, slow), [1, 2, 3, 4]);
});
test("drain 保持提交顺序", async () => {
  const jobs = [3, 1, 2];
  assert.deepEqual(await drain(jobs, slow), [3, 1, 2]);
});

import test from "node:test";
import assert from "node:assert/strict";
import { total } from "../src/worker.js";

test("total 累加异步结果", async () => {
  const r = await total([1, 2, 3], (n) => Promise.resolve(n * 10));
  assert.equal(r, 60);
});

