test("drain 在完成顺序被打乱时仍按提交顺序返回", async () => {
  // 完成顺序与提交顺序相反，防止用「并发 + 按完成顺序落位」糊弄过去
  const lag = (n, ms) => new Promise((r) => setTimeout(() => r(n), ms));
  const jobs = [["a", 30], ["b", 20], ["c", 0]];
  assert.deepEqual(await drain(jobs, (j) => lag(j[0], j[1])), ["a", "b", "c"]);
});

